import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"PaperSeek online","description":"","frontmatter":{},"headers":[],"relativePath":"online/index.md","filePath":"online/index.md","lastUpdated":1793111003000}'),s={name:"online/index.md"};function i(n,e,d,l,h,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="paperseek-online" tabindex="-1">PaperSeek online <a class="header-anchor" href="#paperseek-online" aria-label="Permalink to &quot;PaperSeek online&quot;">​</a></h1><p><a href="https://paperseek.app/" target="_blank" rel="noreferrer">Open PaperSeek</a> to search from your browser. The online edition shares the Community search workflow, results, bibliometrics, citation map, and experimental review workspace. PaperSeek online is in public beta.</p><p>New here? <a href="./../get-started/online">Run your first search online</a>.</p><h2 id="two-ways-to-run-a-task" tabindex="-1">Two ways to run a task <a class="header-anchor" href="#two-ways-to-run-a-task" aria-label="Permalink to &quot;Two ways to run a task&quot;">​</a></h2><p>Switch at any time from the account menu at the bottom of the sidebar, or in <strong>Settings › Model service</strong>.</p><table tabindex="0"><thead><tr><th></th><th>PaperSeek Service</th><th>Your own key</th></tr></thead><tbody><tr><td>Models</td><td>Provided by PaperSeek, chosen from a list</td><td>Your saved model connections</td></tr><tr><td>Keys</td><td>None needed</td><td>Saved to your account in Settings</td></tr><tr><td>Credits</td><td>Uses daily credits</td><td>No credits</td></tr><tr><td>Account</td><td>Required</td><td>Required to save history; a signed-out temporary search is possible</td></tr></tbody></table><p>Model keys and data-source keys are separate. A model API key does not grant access to a literature database.</p><ul><li><a href="./credits">Service &amp; credits</a> — task costs, refunds, and the daily refill.</li><li><a href="./byok">Your own keys</a> — bring your own model and data-source keys.</li><li><a href="./privacy">Data &amp; privacy</a> — how keys are stored, and searching without an account.</li><li><a href="./account">Your account</a> — sign-in methods and account settings.</li></ul><h2 id="when-your-task-is-queued" tabindex="-1">When your task is queued <a class="header-anchor" href="#when-your-task-is-queued" aria-label="Permalink to &quot;When your task is queued&quot;">​</a></h2><p>The site limits how many tasks run at the same time. A queued task shows its position and starts automatically when there is room; there is no need to submit it again. You can leave the queue while waiting, which returns any credits.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../guide/search">Search the literature</a> — questions, budgets, stages, and cancellation.</li><li><a href="./../reference/troubleshooting">Troubleshooting</a> — symptoms, causes, and fixes.</li></ul>',12)])])}const m=t(s,[["render",i]]);export{p as __pageData,m as default};
